import openpyxl

wb = openpyxl.load_workbook('/root/output/rar_result.xlsx')
ws_value = wb['Value']
ws_volume = wb['Volume']

# Extract country names from headers - improved
def extract_country(header):
    if header:
        if ':' in header:
            country = header.split(':')[0].strip()
            # Normalize Czechia variants
            if 'Czechia' in country or 'Czech' in country:
                return 'Czechia'
            # Normalize Kyrgyz variants  
            if 'Kyrgyz' in country:
                return 'Kyrgyz Republic'
            return country
    return header

# Value sheet countries with 2025 data
print("=== VALUE SHEET - Countries with 2025 data ===")
value_countries = {}
for col in range(3, ws_value.max_column + 1):
    header = ws_value.cell(row=1, column=col).value
    value_2025 = ws_value.cell(row=18, column=col).value
    if value_2025 is not None and value_2025 != '' and str(value_2025) != '#N/A':
        country = extract_country(header)
        value_countries[country] = {'col': col, 'value': value_2025, 'header': header}
        print(f"{country}: {value_2025} (col {col})")

print(f"\nValue countries: {list(value_countries.keys())}")

# Volume sheet countries with 2025 data
print("\n=== VOLUME SHEET - Countries with 2025 data ===")
volume_countries = {}
for col in range(3, ws_volume.max_column + 1):
    header = ws_volume.cell(row=1, column=col).value
    value_2025 = ws_volume.cell(row=18, column=col).value
    if value_2025 is not None and value_2025 != '' and str(value_2025) != '#N/A':
        country = extract_country(header)
        volume_countries[country] = {'col': col, 'volume': value_2025, 'header': header}
        print(f"{country}: {value_2025} (col {col})")

print(f"\nVolume countries: {list(volume_countries.keys())}")

# Find countries in Volume but not in Value
additional_countries = set(volume_countries.keys()) - set(value_countries.keys())
print(f"\nAdditional countries from Volume (not in Value): {additional_countries}")
for country in additional_countries:
    print(f"  {country}: Volume = {volume_countries[country]['volume']} million troy ounces")
